-- MYSTIC : recherchés (1 par zone, réapparition 4 à 6 h, un succès chacun). Généré par generer_recherches.py. Rejouable.
CREATE TABLE IF NOT EXISTS nekfeu_recherches (MonsterId INT NOT NULL PRIMARY KEY, Nom VARCHAR(100) NOT NULL, SubAreasCSV VARCHAR(255) NOT NULL, GradeMin INT NOT NULL, GradeMax INT NOT NULL, NiveauMin INT NOT NULL, AchievementId INT NOT NULL, ProchainSpawn DATETIME NULL) DEFAULT CHARSET=utf8;
DELETE FROM nekfeu_recherches;
